import { useState } from "react";
import NoteContext from "./noteContext";

const NoteState = (props) => {
  const host = "http://localhost:5000";
  const notesInitial = []

  const [notes, setNotes] = useState(notesInitial);

  //fetch a note
  const getNotes = async() => {
    try {
      //api call here
      const response = await fetch(`${host}/api/notes/fetchallnotes`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        }
      });
      const json = await response.json()
      console.log("Fetched notes:", json)
      setNotes(json)
    } catch (error) {
      console.error("Error fetching notes:", error);
    }
  }

  //Add a note
  const addNote = async(title, description, tag) => {
    try {
      //api call here
      const response = await fetch(`${host}/api/notes/addnote`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        },
        body: JSON.stringify({title, description, tag}),
      });

      const json = await response.json();
      console.log("Added note:", json);
      
      if (response.ok) {
        // Use the actual response from API instead of hardcoded object
        setNotes(notes.concat(json));
      } else {
        console.error("Failed to add note:", json);
      }
    } catch (error) {
      console.error("Error adding note:", error);
    }
  };

  //Delete a Note
  const deleteNote = async(id) => {
    try {
      const response = await fetch(`${host}/api/notes/deletenote/${id}`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        }
      });
      const json = await response.json();
      console.log("Delete response:", json)
      
      if (response.ok) {
        console.log("Deleting the note with id: " + id);
        const newNotes = notes.filter((note) => {
          return note._id !== id;
        });
        setNotes(newNotes);
      } else {
        console.error("Failed to delete note:", json);
      }
    } catch (error) {
      console.error("Error deleting note:", error);
    }
  };

  //Update a note
  const editNote = async (id, title, description, tag) => {
    try {
      //api call here
      const response = await fetch(`${host}/api/notes/editNote/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "auth-token":
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
        },
        body: JSON.stringify({title, description, tag}),
      });
      
      const json = await response.json();
      console.log("Edit response:", json);

      // Check if API call was successful
      if (response.ok) {
        // Update the notes in state - create new array with updated note
        const newNotes = notes.map((note) =>
          note._id === id ? { ...note, title, description, tag } : note
        );
        setNotes(newNotes);
        console.log("Note updated successfully in state");
      } else {
        console.error("Failed to update note:", json);
      }
    } catch (error) {
      console.error("Error updating note:", error);
    }
  };

  return (
    <NoteContext.Provider value={{ notes, addNote, deleteNote, editNote, getNotes }}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
